import type { FeishuResourceBinding, FeishuTableManifest } from '@aeolus/feishu-table-sdk';
const FEISHU_HOST = 'https://bytedance.larkoffice.com';
export function findBinding(bindingId: string): FeishuResourceBinding | undefined {
  return (window.webApplicationManifest as FeishuTableManifest | undefined)?.feishuResourceBindings?.find((b) => b.bindingId === bindingId);
}
export function feishuResourceUrl(binding: FeishuResourceBinding | undefined) {
  if (binding?.resourceType === 'sheetRange') return `${FEISHU_HOST}/sheets/${binding.spreadsheetToken}${binding.sheetId ? `?sheet=${binding.sheetId}` : ''}`;
  if (binding?.resourceType === 'bitableRecords') return `${FEISHU_HOST}/base/${binding.appToken}${binding.tableId ? `?table=${binding.tableId}` : ''}`;
}
export function sourceUrl() { return feishuResourceUrl(findBinding('airwaybillRecords')); }
